<!doctype html>
<html lang="vi"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#224086">
<title>@yield('title', 'The HBG NFC')</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,Arial,sans-serif;color:#1c2840;background:#f3f6fb}*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}a{color:#224086;text-decoration:none}a:hover{text-decoration:underline}.mobile-only{display:none}.container{max-width:1050px;margin:0 auto;padding:24px}.panel{background:#fff;border-radius:18px;padding:28px;box-shadow:0 8px 28px #15284813}.top{background:#224086;color:white;padding:14px max(18px,calc((100vw - 1050px)/2 + 24px));display:flex;align-items:center;justify-content:space-between;gap:16px}.top a{color:white}.top-nav{display:flex;align-items:center;justify-content:flex-end;gap:10px 16px;flex-wrap:wrap}.top-nav form{margin:0}.brand{font-size:18px;font-weight:850;letter-spacing:1.5px}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:18px}.page-heading h1{margin:0 0 5px}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:42px;border:0;border-radius:10px;padding:10px 16px;background:#224086;color:#fff;cursor:pointer;font-size:14px;text-align:center}.btn:hover{opacity:.9;color:white;text-decoration:none}.btn.secondary{background:#ecf0fa;color:#224086}.btn.gold{background:#d9a65b;color:#1c2840}.btn.danger{background:#fff0f1;color:#b52436}.input{width:100%;min-height:44px;border:1px solid #ced7e6;border-radius:9px;padding:11px 12px;font:inherit;background:#fff}.field{margin-bottom:15px}.field label{display:block;font-size:13px;font-weight:650;margin-bottom:6px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.muted{color:#68758c;font-size:13px}.alert{padding:12px 14px;background:#ecf8ee;color:#136b35;border-radius:10px;margin-bottom:16px}.error{color:#b52436;font-size:13px;margin-top:4px}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #e8edf5;padding:12px 8px;font-size:14px}th{font-size:12px;color:#66728b}.actions{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.actions form{margin:0}.break{overflow-wrap:anywhere;word-break:break-word}.cardphoto{height:112px;width:112px;object-fit:cover;border-radius:50%;border:5px solid white;box-shadow:0 5px 18px #15284822}.placeholder{display:flex;align-items:center;justify-content:center;background:#e7edfb;color:#224086;font-size:42px;font-weight:800}.profile{max-width:480px;margin:35px auto;padding:0;overflow:hidden}.hero{background:linear-gradient(145deg,#224086,#0e2459);color:white;padding:36px 24px 28px;text-align:center}.hero h1{margin:12px 0 5px;font-size:25px}.tag{display:inline-block;padding:5px 11px;background:#ffffff20;border-radius:20px;font-size:12px}.details{padding:23px}.detail{border-bottom:1px solid #eef0f6;padding:12px 0}.detail small{display:block;color:#6e7891;margin-bottom:3px}.detail span{font-weight:550;overflow-wrap:anywhere}.profile-footer{border-top:1px solid #eef0f6;padding:17px;text-align:center;color:#68758c;font-size:12px}
@media(max-width:650px){body{font-size:15px}.desktop-only{display:none}.mobile-only{display:block}.container{padding:14px 12px 28px}.panel{padding:16px;border-radius:14px}.top{padding:12px;align-items:stretch;flex-direction:column;gap:11px}.top-nav{justify-content:flex-start;gap:8px}.top-nav>a,.top-nav .btn{min-height:38px;padding:8px 11px;border-radius:9px}.brand{font-size:15px;letter-spacing:1px}.page-heading{align-items:stretch;flex-direction:column;margin-bottom:14px}.page-heading h1,.container>h1{font-size:24px;line-height:1.2}.page-heading>.btn{width:100%}.grid{grid-template-columns:1fr}.profile{margin:12px auto}.form-actions>.btn,.form-actions>button{flex:1}.mobile-cards{display:block}.mobile-cards thead{display:none}.mobile-cards tbody{display:grid;gap:12px}.mobile-cards tr{display:block;padding:14px;border:1px solid #e2e8f0;border-radius:13px;background:#fff;box-shadow:0 3px 12px #1528480d}.mobile-cards td{display:grid;grid-template-columns:minmax(90px,34%) minmax(0,1fr);gap:10px;border:0;padding:6px 0;white-space:normal;overflow-wrap:anywhere}.mobile-cards td::before{content:attr(data-label);font-size:11px;font-weight:750;letter-spacing:.35px;text-transform:uppercase;color:#718096}.mobile-cards td.mobile-primary{display:block;padding-bottom:10px;margin-bottom:4px;border-bottom:1px solid #edf1f6}.mobile-cards td.mobile-primary::before{display:none}.mobile-cards td.mobile-actions{display:block;padding-top:10px}.mobile-cards td.mobile-actions::before{display:none}.mobile-cards td[colspan]{display:block;text-align:center}.mobile-cards td[colspan]::before{display:none}.mobile-cards .actions{gap:8px}.mobile-cards .actions .btn,.mobile-cards .actions button{min-height:38px}.pagination{overflow-x:auto}.login-shell{margin-top:3vh!important}.login-shell .panel{padding:22px 18px}}
</style>
</head><body>@yield('body')</body></html>
